import com.mongodb.client.MongoClients; import com.mongodb.client.MongoClient; import com.mongodb.client.MongoDatabase; import org.bson.Document; import java.util.function.Consumer; public class MongoDebug { public static void main(String[] args) { System.out.println("Connecting to MongoDB..."); try (MongoClient mongoClient = MongoClients.create("mongodb://localhost:27017")) { System.out.println("Connected!"); System.out.println("Databases:"); mongoClient.listDatabaseNames().forEach((Consumer<String>) System.out::println); MongoDatabase db = mongoClient.getDatabase("demandatech"); System.out.println("\nCollections in demandatech:"); db.listCollectionNames().forEach((Consumer<String>) System.out::println); System.out.println("\nDocuments in funcionarios: " + db.getCollection("funcionarios").countDocuments()); for (Document doc : db.getCollection("funcionarios").find()) { System.out.println(doc.toJson()); } } catch (Exception e) { e.printStackTrace(); } } }
